import{_ as e,o as n,c as o,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-04-23","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-04-23","date":"2025-04-23T00:00:00.000Z","updated":"2025-04-26T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","Lua脚本","Bucket Index Snapshots"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-04-23.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-04-23.md","lastUpdated":1780460162000}'),a={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-04-23.md"};function r(i,t,l,g,u,h){return n(),o("div",null,[...t[0]||(t[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>: 2025年4月23日<br><strong>参会人员</strong>: Matt, Yehuda, Andre, Philip, Dixon, Casey, 及其他相关开发人员<br><strong>会议主题</strong>: Ceph RGW重构讨论，主要涉及bucket index snapshots增强和Lua脚本功能改进。</p><h4 id="_1-bucket-index-snapshots-讨论" tabindex="-1">1. <strong>Bucket Index Snapshots 讨论</strong> <a class="header-anchor" href="#_1-bucket-index-snapshots-讨论" aria-label="Permalink to &quot;1. **Bucket Index Snapshots 讨论**&quot;">​</a></h4><ul><li><strong>背景</strong>: 讨论了在Ceph中实现bucket index snapshots功能的方法，并探讨如何将其集成到现有代码库中。</li><li><strong>主要议题</strong>: <ul><li><strong>数据结构变更</strong>: 为了支持bucket snapshots功能，需要在T版本中引入基本的数据结构变更。</li><li><strong>多站点同步问题</strong>: 当前功能仅在单个zone内生效，未来计划支持多站点同步。</li><li><strong>实验性功能</strong>: 该功能计划作为实验性功能发布，以确保用户在升级时能够顺利过渡。</li></ul></li><li><strong>决定事项</strong>: <ul><li>需要在T版本中先引入数据结构变更。</li><li>未来需要进一步讨论多站点同步的具体实现。</li></ul></li><li><strong>后续行动</strong>: <ul><li>Yehuda将提交PR，包含数据结构变更。</li></ul></li></ul><h4 id="_2-lua脚本功能增强讨论" tabindex="-1">2. <strong>Lua脚本功能增强讨论</strong> <a class="header-anchor" href="#_2-lua脚本功能增强讨论" aria-label="Permalink to &quot;2. **Lua脚本功能增强讨论**&quot;">​</a></h4><ul><li><strong>背景</strong>: 讨论如何增强Lua脚本的功能，使其更加适合生产环境使用，并满足特定需求。</li><li><strong>主要议题</strong>: <ul><li><strong>功能需求</strong>: Andre提出需要增加Lua脚本的hook点，特别是在用户认证后和bucket信息加载后。</li><li><strong>性能与安全性</strong>: 讨论了Lua脚本的性能问题，特别是与外部服务通信时的连接开销。</li><li><strong>背景脚本</strong>: 提出了使用背景脚本（background script）来处理与外部服务的通信。</li></ul></li><li><strong>决定事项</strong>: <ul><li>增加Lua脚本的hook点。</li><li>需要进一步讨论如何在Lua脚本中处理与外部服务的通信。</li></ul></li><li><strong>后续行动</strong>: <ul><li>Andre将尝试实现相关功能。</li></ul></li></ul><h4 id="_3-其他议题" tabindex="-1">3. <strong>其他议题</strong> <a class="header-anchor" href="#_3-其他议题" aria-label="Permalink to &quot;3. **其他议题**&quot;">​</a></h4><ul><li><strong>Bucket Notifications</strong>: 讨论了bucket notifications的相关功能，但由于时间关系，决定下次会议再进行详细讨论。</li></ul><p><strong>会议结束时间</strong>: 约1小时<br><strong>下次会议计划</strong>: 未定</p>',9)])])}const d=e(a,[["render",r]]);export{_ as __pageData,d as default};
